-- AUTO-GENERATED by pz_craft_loops/rotation_fix.py -- do not edit by hand.
-- Face offsets for moveable rotation. The engine only generates Noffset/Eoffset/Soffset/Woffset
-- when a tileset groups at most 4 tiles under one GroupName + CustomName; several packs group far
-- more (Dirkies kitchen counters: 52), so those pieces could not be rotated when placed from the
-- inventory. Offsets come from our Knox Buildworks definitions (which sprites are the faces of
-- one piece). Applied once tile definitions are loaded.
local OFFSETS = {
    ["tikitown_furniture_bedroom_01_24"] = { Eoffset = 1, Noffset = 3, Woffset = 2 },
    ["tikitown_furniture_bedroom_01_25"] = { Noffset = 2, Soffset = -1, Woffset = 1 },
    ["tikitown_furniture_bedroom_01_26"] = { Eoffset = -1, Noffset = 1, Soffset = -2 },
    ["tikitown_furniture_bedroom_01_27"] = { Eoffset = -2, Soffset = -3, Woffset = -1 },
    ["tikitown_furniture_bedroom_02_24"] = { Eoffset = 1, Noffset = 3, Woffset = 2 },
    ["tikitown_furniture_bedroom_02_25"] = { Noffset = 2, Soffset = -1, Woffset = 1 },
    ["tikitown_furniture_bedroom_02_26"] = { Eoffset = -1, Noffset = 1, Soffset = -2 },
    ["tikitown_furniture_bedroom_02_27"] = { Eoffset = -2, Soffset = -3, Woffset = -1 },
    ["tikitown_furniture_bedroom_03_24"] = { Eoffset = 1, Noffset = 3, Woffset = 2 },
    ["tikitown_furniture_bedroom_03_25"] = { Noffset = 2, Soffset = -1, Woffset = 1 },
    ["tikitown_furniture_bedroom_03_26"] = { Eoffset = -1, Noffset = 1, Soffset = -2 },
    ["tikitown_furniture_bedroom_03_27"] = { Eoffset = -2, Soffset = -3, Woffset = -1 },
    ["tikitown_furniture_bedroom_04_24"] = { Eoffset = 1, Noffset = 3, Woffset = 2 },
    ["tikitown_furniture_bedroom_04_25"] = { Noffset = 2, Soffset = -1, Woffset = 1 },
    ["tikitown_furniture_bedroom_04_26"] = { Eoffset = -1, Noffset = 1, Soffset = -2 },
    ["tikitown_furniture_bedroom_04_27"] = { Eoffset = -2, Soffset = -3, Woffset = -1 },
}

local applied = false
local function apply()
    if applied then return end
    applied = true
    local done, missing = 0, 0
    for spriteName, values in pairs(OFFSETS) do
        local sprite = getSprite(spriteName)
        local props = sprite and sprite:getProperties() or nil
        if props then
            for key, value in pairs(values) do
                pcall(function() props:set(key, tostring(value)) end)
            end
            pcall(function() props:CreateKeySet() end)
            done = done + 1
        else
            missing = missing + 1
        end
    end
    print("[KBWCommunity] Rotation: face offsets set on " .. tostring(done) .. " sprite(s), "
        .. tostring(missing) .. " not loaded")
end

if Events.OnLoadedTileDefinitions then Events.OnLoadedTileDefinitions.Add(apply) end
Events.OnGameStart.Add(apply)
if Events.OnServerStarted then Events.OnServerStarted.Add(apply) end
